<!doctype html><html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>RISCP 支付中心</title><style>body{font-family:system-ui;margin:0;background:#f5f6f8;color:#111827}.top{background:#111827;color:#fff;padding:18px 24px}.wrap{max-width:1200px;margin:24px auto;padding:0 16px}.grid{display:grid;grid-template-columns:1fr 1fr;gap:16px}.card{background:#fff;border-radius:12px;padding:18px;box-shadow:0 1px 3px #0001}table{width:100%;border-collapse:collapse}th,td{text-align:left;padding:11px;border-bottom:1px solid #eee}.pill{padding:3px 8px;border-radius:99px;background:#dcfce7;color:#166534}.input,select{padding:10px;width:100%;box-sizing:border-box;border:1px solid #d1d5db;border-radius:8px;margin:6px 0 12px}.btn{border:0;border-radius:8px;padding:10px 14px;background:#111827;color:#fff;cursor:pointer}.hint{font-size:13px;color:#6b7280}.route{display:grid;grid-template-columns:1fr 1fr;gap:12px}</style></head><body><div class="top"><strong>RISCP Payment Center</strong> · 支付机构与人工路由</div><div class="wrap"><div class="card"><h2>支付机构</h2><table><thead><tr><th>机构</th><th>Code</th><th>状态</th></tr></thead><tbody id="providers"></tbody></table></div><div class="grid" style="margin-top:16px"><div class="card"><h2>门店支付账户</h2><label class="hint">Tenant ID</label><input id="tenant" class="input" placeholder="UUID"><label class="hint">Store ID</label><input id="store" class="input" placeholder="UUID"><button class="btn" onclick="loadAccounts()">查询账户</button><div id="accounts" style="margin-top:14px"></div></div><div class="card"><h2>人工切换路由</h2><label class="hint">支付方式</label><select id="method"><option value="wechat">微信支付</option><option value="alipay">支付宝</option><option value="bank_card">银行卡</option></select><label class="hint">Channel ID</label><input id="channel" class="input" placeholder="UUID"><label class="hint">操作人</label><input id="operator" class="input" placeholder="管理员ID"><label class="hint">切换原因</label><input id="reason" class="input" placeholder="例如：通联费率调整"><button class="btn" onclick="switchRoute()">立即切换</button><p id="result" class="hint"></p></div></div></div><script>async function loadProviders(){const r=await fetch('/api/v1/admin/payments/providers');const d=await r.json();document.querySelector('#providers').innerHTML=(d.data||[]).map(x=>`<tr><td>${x.name}</td><td>${x.code}</td><td><span class="pill">${x.status}</span></td></tr>`).join('')||'<tr><td colspan="3">暂无机构</td></tr>'}async function loadAccounts(){const t=document.querySelector('#tenant').value,s=document.querySelector('#store').value;if(!t)return alert('请填写 Tenant ID');const r=await fetch('/api/v1/admin/payments/accounts?tenant_id='+encodeURIComponent(t)+(s?'&store_id='+encodeURIComponent(s):''));const d=await r.json();document.querySelector('#accounts').innerHTML=(d.data||[]).map(x=>`<div style="padding:10px;border-bottom:1px solid #eee"><strong>${x.provider_name}</strong><br><span class="hint">商户号：${x.merchant_no||'-'} · ${x.status}</span></div>`).join('')||'暂无账户'}async function switchRoute(){const body={tenant_id:document.querySelector('#tenant').value,store_id:document.querySelector('#store').value,payment_method:document.querySelector('#method').value,channel_id:document.querySelector('#channel').value,operator_id:document.querySelector('#operator').value,reason:document.querySelector('#reason').value};const r=await fetch('/api/v1/admin/payments/routes',{method:'POST',headers:{'Content-Type':'application/json','Accept':'application/json'},body:JSON.stringify(body)});const d=await r.json();document.querySelector('#result').textContent=r.ok?'路由切换成功':'切换失败：'+(d.message||JSON.stringify(d))}loadProviders();</script></body></html>